package solution

import "testing"

func TestRegistryLifecycleAndOrdering(t *testing.T) {
	r := NewRegistry()
	if got := r.List(""); got == nil || len(got) != 0 {
		t.Fatalf("List(empty) = %#v, want non-nil empty slice", got)
	}
	for _, tc := range []struct{ name, scope, release string }{
		{"zeta", "prod", "v1"},
		{"alpha", "prod", "v2"},
		{"alpha", "dev", "v3"},
	} {
		got, err := r.Create(tc.name, tc.scope, tc.release)
		if err != nil {
			t.Fatalf("Create(%q,%q,%q): %v", tc.name, tc.scope, tc.release, err)
		}
		want := Component{Name: tc.name, Scope: tc.scope, Release: tc.release, Quota: 64}
		if got != want {
			t.Fatalf("Create result = %#v, want %#v", got, want)
		}
	}

	got := r.List("prod")
	if len(got) != 2 || got[0].Name != "alpha" || got[1].Name != "zeta" {
		t.Fatalf("List(prod) = %#v", got)
	}
	got[0] = Component{Name: "corrupted"}
	again := r.List("prod")
	if len(again) != 2 || again[0].Name != "alpha" || again[0].Quota != 64 {
		t.Fatalf("returned list aliases registry: %#v", again)
	}

	component, err := r.Get("zeta", "prod")
	if err != nil || component != (Component{Name: "zeta", Scope: "prod", Release: "v1", Quota: 64}) {
		t.Fatalf("Get = %#v, %v", component, err)
	}
	if err := r.Delete("zeta", "prod"); err != nil {
		t.Fatalf("Delete existing: %v", err)
	}
	if _, err := r.Get("zeta", "prod"); err == nil {
		t.Fatal("Get after Delete succeeded")
	}
	if err := r.Delete("zeta", "prod"); err == nil {
		t.Fatal("Delete missing component succeeded")
	}
}

func TestRegistryRejectsInvalidAndDuplicateCreates(t *testing.T) {
	r := NewRegistry()
	for _, tc := range []struct{ name, scope, release string }{
		{"", "s", "v"}, {"n", "", "v"}, {"n", "s", ""},
	} {
		if _, err := r.Create(tc.name, tc.scope, tc.release); err == nil {
			t.Fatalf("Create(%q,%q,%q) succeeded", tc.name, tc.scope, tc.release)
		}
	}
	if _, err := r.Create("n", "s", "v1"); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Create("n", "s", "v2"); err == nil {
		t.Fatal("duplicate (scope,name) succeeded")
	}
	if _, err := r.Create("n", "other", "v2"); err != nil {
		t.Fatalf("same name in different scope rejected: %v", err)
	}
	for _, ids := range [][2]string{{"", "s"}, {"n", ""}, {"", ""}} {
		if _, err := r.Get(ids[0], ids[1]); err == nil {
			t.Fatalf("Get(%q,%q) succeeded", ids[0], ids[1])
		}
		if err := r.Delete(ids[0], ids[1]); err == nil {
			t.Fatalf("Delete(%q,%q) succeeded", ids[0], ids[1])
		}
	}
	if got := r.List("missing"); got == nil || len(got) != 0 {
		t.Fatalf("List(missing) = %#v", got)
	}
}

